cat > notes-core/src/lib.rs <<'EOF'
//! notes-core: an in-memory note store with no FFI concerns.

use std::fmt;

/// A stored note.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Note {
    pub id: u64,
    pub text: String,
}

/// Errors from [`NoteStore`].
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum NoteError {
    /// The note text is empty after trimming.
    EmptyText,
}

impl fmt::Display for NoteError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::EmptyText => f.write_str("note text is empty"),
        }
    }
}

impl std::error::Error for NoteError {}

/// Keeps notes in insertion order.
#[derive(Debug, Default)]
pub struct NoteStore {
    notes: Vec<Note>,
    next_id: u64,
}

impl NoteStore {
    /// Creates an empty store.
    pub fn new() -> Self {
        Self::default()
    }

    /// Adds a note and returns it.
    pub fn add(&mut self, text: &str) -> Result<Note, NoteError> {
        let text = text.trim();
        if text.is_empty() {
            return Err(NoteError::EmptyText);
        }
        self.next_id += 1;
        let note = Note {
            id: self.next_id,
            text: text.to_owned(),
        };
        self.notes.push(note.clone());
        Ok(note)
    }

    /// All notes in insertion order.
    pub fn list(&self) -> &[Note] {
        &self.notes
    }

    /// Notes whose text contains `query`, ignoring case.
    pub fn search(&self, query: &str) -> Vec<Note> {
        let query = query.to_lowercase();
        self.notes
            .iter()
            .filter(|n| n.text.to_lowercase().contains(&query))
            .cloned()
            .collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn add_list_search() {
        let mut store = NoteStore::new();
        store.add("Buy milk").unwrap();
        store.add("call Bob").unwrap();
        assert_eq!(store.list().len(), 2);
        assert_eq!(store.search("MILK")[0].text, "Buy milk");
    }

    #[test]
    fn empty_text_is_rejected() {
        assert_eq!(NoteStore::new().add("  "), Err(NoteError::EmptyText));
    }
}
EOF
cat > notes-ffi/src/lib.rs <<'EOF'
//! notes-ffi: Kotlin and Swift bindings for notes-core.
EOF
printf 'target/\n' > .gitignore
git init -q
